insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('ba0879e5-df5e-4864-aa7a-5c2d588f4c25', '621786bc-3c20-4f62-82f6-3dcb7289190a', $$sociaal vertrouwen en vertrouwen in het parlement per Europees land in 2008; figuur (puntenwolk)$$,
   $$wiskunde-a-havo-2016-i-vertrouwen-context1.png$$,
   $$Het Sociaal en Cultureel Planbureau beschrijft om de twee jaar in het rapport ''De Sociale Staat van Nederland'' hoe het met het vertrouwen van Nederlanders gesteld is. Daarbij wordt onder andere onderscheid gemaakt tussen het vertrouwen in de medemens, ook wel het sociale vertrouwen genoemd, en het vertrouwen in het parlement. Beide soorten van vertrouwen worden uitgedrukt in een percentage: hoe hoger het percentage, des te meer vertrouwen. In de figuur wordt het vertrouwen van Nederlanders in het jaar 2008 vergeleken met dat van andere Europeanen. Je kunt bijvoorbeeld aflezen dat in Italië het sociale vertrouwen 30% bedroeg.
figuur: puntenwolk met per land het sociale vertrouwen (%) horizontaal en het vertrouwen in het parlement (%) verticaal; landen AT, BE, CH, DE, DK, ES, FI, FR, GR, IE, IT, LU, NL, NO, PT, SE, UK$$, 'inline'),
  ('2416e0b5-03c6-4ec0-96f3-b15a29e87b0c', '621786bc-3c20-4f62-82f6-3dcb7289190a', $$vertrouwen in het parlement in Nederland vergeleken met overige landen$$,
   $$wiskunde-a-havo-2016-i-vertrouwen-context2.png$$,
   $$In de figuur is af te lezen hoe groot in Nederland het vertrouwen in het parlement was. In sommige van de overige landen was het vertrouwen in het parlement groter.$$, 'inline'),
  ('aac5b572-a88b-4a32-b3b5-1e66ed6a12c6', '621786bc-3c20-4f62-82f6-3dcb7289190a', $$onderzoek 2013: 4292 van 7400 personen hebben vertrouwen; twee uitspraken over 95%-interval [56,6 ; 59,4]$$,
   $$wiskunde-a-havo-2016-i-vertrouwen-context3.png$$,
   $$Voor het onderzoek ''Sociale samenhang'' in 2013 werden gegevens verzameld onder de Nederlandse bevolking. Er deden 7400 aselect getrokken personen aan dit onderzoek mee. Van de deelnemers gaven 4292 personen aan vertrouwen te hebben in de medemens.
Op basis van deze gegevens worden de volgende twee uitspraken gedaan over het percentage Nederlanders dat (in 2013) vertrouwen had in de medemens:
1 Het is meer dan 95% zeker dat het percentage Nederlanders dat vertrouwen had in de medemens, in het interval [56,6 ; 59,4] ligt.
2 Het is minder dan 95% zeker dat het percentage Nederlanders dat vertrouwen had in de medemens, in het interval [56,6 ; 59,4] ligt.
Eén van deze twee uitspraken is juist.$$, 'inline'),
  ('3133ff1c-4a4d-4f56-a317-29b33dec5770', '5a11feeb-ca27-4b22-94cf-e21f0498ae91', $$formule P = 1 + d/10: druk p in bar, diepte d in meter$$,
   $$wiskunde-a-havo-2016-i-duiken-context1.png$$,
   $$Duiken is een mooie sport, maar niet ongevaarlijk. Het grootste gevaar waar duikers mee te maken krijgen, is de druk van het water op het lichaam. Deze druk wordt hoger naarmate de duiker dieper duikt. Een formule die het verband tussen de druk en de diepte weergeeft, luidt:
P = 1 + d/10
Hierin is p de druk van het water op het lichaam in bar en d de diepte onder water in meter.$$, 'inline'),
  ('b922ec5b-9082-4457-9c57-3923f6bd4580', '5a11feeb-ca27-4b22-94cf-e21f0498ae91', $$advies: druk niet hoger dan 5 bar$$,
   $$wiskunde-a-havo-2016-i-duiken-context2.png$$,
   $$Duikorganisaties adviseren recreatieve duikers om de druk van het water op het lichaam niet hoger te laten worden dan 5 bar.$$, 'inline'),
  ('39f15772-2891-4f6e-93bf-c53c87eea5b5', '5a11feeb-ca27-4b22-94cf-e21f0498ae91', $$perslucht L in barliter = inhoud × druk; formule L = 20 · p · T$$,
   $$wiskunde-a-havo-2016-i-duiken-context3.png$$,
   $$Bij een duik wordt een duikfles meegenomen met perslucht om onder water te kunnen ademen. Perslucht is lucht die onder grote druk wordt samengeperst. De hoeveelheid perslucht L wordt uitgedrukt in barliter. De waarde van L wordt berekend door de inhoud van de fles (in liter) te vermenigvuldigen met de druk (in bar). Als je bijvoorbeeld een duikfles van 15 liter vult tot een druk van 200 bar, dan is de hoeveelheid perslucht in de fles 15 × 200 = 3000 barliter.
Om de benodigde hoeveelheid perslucht voor een duik te berekenen, maakt een duiker gebruik van de volgende formule:
L = 20 · p · T
Hierin is L de hoeveelheid perslucht in barliter, p de druk van het water op het lichaam in bar en T de duiktijd in minuten. De duiktijd is de tijd die de duiker onder water is.$$, 'inline'),
  ('9f4a918e-b9ca-4aea-a872-890ccb7fb62c', '5a11feeb-ca27-4b22-94cf-e21f0498ae91', $$Jan: duik van drie kwartier naar 19 meter, fles van 12 liter tot 200 bar$$,
   $$wiskunde-a-havo-2016-i-duiken-context4.png$$,
   $$Jan wil een duik gaan maken van drie kwartier naar een diepte van
19 meter. Hij gebruikt een duikfles van 12 liter en vult deze tot een druk van 200 bar.$$, 'inline'),
  ('be64420d-89bf-42b2-bdc1-6579c9b5efe4', '5a11feeb-ca27-4b22-94cf-e21f0498ae91', $$Dennis: 2400 barliter, diepte hoogstens 25 meter; grafiek van T tegen d$$,
   $$wiskunde-a-havo-2016-i-duiken-context5.png$$,
   $$Het Grevelingenmeer in de provincie Zeeland is een groot meer, dat niet overal even diep is. Dennis gaat duiken in een gedeelte van dit meer, waar het nergens dieper dan 25 meter is. Hij vult zijn duikfles met 2400 barliter perslucht. Met deze hoeveelheid perslucht heeft Dennis verschillende mogelijkheden voor zijn duik. Hij kan bijvoorbeeld kiezen voor een niet al te diepe duik waarbij hij lang onder water kan blijven, of voor een diepere duik met een kortere duiktijd. Dennis kan voor de keuze van zijn duik een grafiek tekenen, waarbij hij de duiktijd T uitzet tegen de diepte d.$$, 'inline'),
  ('859de590-2343-4fe3-b43f-c718484cbef7', '5a11feeb-ca27-4b22-94cf-e21f0498ae91', $$uitwerkbijlage vraag 6: assenstelsel duiktijd T tegen diepte d$$,
   $$wiskunde-a-havo-2016-i-duiken-context6.png$$,
   $$6
uitwerkbijlage: leeg assenstelsel met duiktijd T (minuten, 0 t/m 100) verticaal en diepte d (meter, 5 t/m 25) horizontaal$$, 'uitwerkbijlage'),
  ('2062287b-f798-4940-9c99-cafa32af2f6f', '0282eadb-e4d0-4cf6-a8ce-1afb6cb79d0f', $$onderzoek naar binnenkomende links per Wikipedia-artikel$$,
   $$wiskunde-a-havo-2016-i-links-naar-wikipedia-artikelen-context1.png$$,
   $$Wikipedia is een encyclopedie op internet, waarin veel artikelen over diverse onderwerpen te vinden zijn. In die artikelen wordt vaak met een link verwezen naar andere artikelen. Van elk artikel dat op
24 januari 2009 in het Engelse Wikipedia voorkwam, is onderzocht hoeveel links in andere artikelen naar het betreffende artikel verwezen. Deze links worden de binnenkomende links genoemd. Het aantal binnenkomende links per artikel is geteld. De resultaten van dit onderzoek staan in figuur 1 en tabel 1.$$, 'inline'),
  ('07e5856d-e8d7-42f1-ae55-c7696cf22974', '0282eadb-e4d0-4cf6-a8ce-1afb6cb79d0f', $$figuur 1 (staafdiagram aantal artikelen per aantal binnenkomende links) en tabel 1 (frequentietabel, totaal 2 575 308)$$,
   $$wiskunde-a-havo-2016-i-links-naar-wikipedia-artikelen-context2.png$$,
   $$figuur 1: staafdiagram van het aantal artikelen per aantal binnenkomende links (0 t/m 50); verticale as aantal artikelen (0 t/m 250 000)
tabel 1
aantal binnenkomende links | aantal artikelen
0 | 133 515
1 of 2 | 465 915
3 t/m 10 | 763 683
11 of meer | 1 212 195
totaal | 2 575 308$$, 'inline'),
  ('53f7c389-664b-4d77-aefe-8f62454e9fbc', '0282eadb-e4d0-4cf6-a8ce-1afb6cb79d0f', $$43% van de artikelen met 11 of meer links heeft 50 of meer links; lange staart$$,
   $$wiskunde-a-havo-2016-i-links-naar-wikipedia-artikelen-context3.png$$,
   $$In het onderzoek valt onder andere het volgende te lezen: “43% van de artikelen met 11 of meer binnenkomende links heeft zelfs
50 of meer binnenkomende links. Dat zijn de echt belangrijke artikelen, waarnaar vaak verwezen wordt.”
De lange staart van artikelen waarnaar 50 of meer keer verwezen wordt, is niet aangegeven in figuur 1. Deze staart hoort er uiteraard wel bij.$$, 'inline'),
  ('fa80634f-c6a1-49bc-915b-0614d5cbe18c', '0282eadb-e4d0-4cf6-a8ce-1afb6cb79d0f', $$gemiddelde, modus en mediaan zijn alle drie verschillend$$,
   $$wiskunde-a-havo-2016-i-links-naar-wikipedia-artikelen-context4.png$$,
   $$De drie centrummaten van het aantal binnenkomende links, namelijk het gemiddelde, de modus en de mediaan, zijn alle drie verschillend.$$, 'inline'),
  ('796b38e3-5360-4e13-b85a-b2b13c0a757c', '0282eadb-e4d0-4cf6-a8ce-1afb6cb79d0f', $$tabel 2 (aantal sterren bij aantal binnenkomende links) en figuur 2 (boxplot van het aantal sterren)$$,
   $$wiskunde-a-havo-2016-i-links-naar-wikipedia-artikelen-context5.png$$,
   $$De onderzoekers kwalificeren het belang van elk artikel door het te voorzien van een aantal hele en/of halve sterren. Artikelen die geen binnenkomende links hebben, zijn volgens hen niet of nauwelijks van belang en krijgen daarom 0 sterren. De belangrijkste artikelen krijgen 5 sterren. In tabel 2 kun je aflezen welk aantal sterren bij welk aantal binnenkomende links hoort.
tabel 2
aantal binnenkomende links | belang (aantal sterren)
0 | 0
1 | ½
2 | 1
3 of 4 | 1½
5 of 6 | 2
7 of 8 | 2½
9 of 10 | 3
11 t/m 19 | 3½
20 t/m 29 | 4
30 t/m 49 | 4½
50 of meer | 5
In figuur 2 is de boxplot getekend die hoort bij het belang, uitgedrukt in het aantal sterren.
figuur 2: boxplot van het belang (aantal sterren): minimum 0, Q1 1,5, mediaan 3, Q3 4,5, maximum 5$$, 'inline'),
  ('63345560-e053-4773-8846-49cb280b529f', '0282eadb-e4d0-4cf6-a8ce-1afb6cb79d0f', $$boxplot met tabel 2 versus staafdiagram$$,
   $$wiskunde-a-havo-2016-i-links-naar-wikipedia-artikelen-context6.png$$,
   $$Bepaalde informatie over het aantal binnenkomende links kan gemakkelijk uit de boxplot in combinatie met tabel 2 afgelezen worden. Voor andere informatie is het oorspronkelijke staafdiagram juist gemakkelijker.$$, 'inline'),
  ('0ad63bee-f152-454d-9927-e81ac12ab8d5', '49253b7b-b9a4-4551-adc1-54871cd9312b', $$trainingsschema Start to Run (figuur): programma met + (1 minuut hardlopen) en 0 (1 minuut wandelen)$$,
   $$wiskunde-a-havo-2016-i-start-to-run-context1.png$$,
   $$Als je begint met hardlopen, moet je in het begin niet te snel of te lang willen lopen. Het is veel beter om rustig aan te beginnen en eerst een goede conditie op te bouwen. Een trainingsprogramma dat veel gebruikt wordt, heet Start to Run. Daarbij moet je tien weken lang drie keer per week hardlopen, waarbij je gaandeweg steeds langere periodes aan één stuk hardloopt. In de figuur zie je hoe het trainingsprogramma eruitziet.
figuur: trainingsschema Start to Run
Weeknummer | Trainingsdag | Programma | Totaal aantal minuten
1 | 1 | +0+0++00++00+++000 | 18
1 | 2 | +0+0++00+++000+++000 | 20
1 | 3 | +0++00++00+++000+++000 | 22
2 | 1 | +0++00++00+++000+++000 | 22
2 | 2 | ++00+++000+++000+++000 | 22
2 | 3 | +0++00+++000+++000+++000 | 24
3 en 4 | 1 | +0++00+++000+++000+++000 | 24
3 en 4 | 2 | ++00++0++0++0++0++0++0++0 | 25
3 en 4 | 3 | +0++00++++000++++000+++++0 | 26
5 en 6 | 1 | ++00+++00+++++000+++++000+++++00 | 32
5 en 6 | 2 | ++0+++00++++++00++++++00+++++++00 | 33
5 en 6 | 3 | ++00++++00+++++00++++++00+++++++00 | 34
7 | 1 | +++++0++++++00+++++++00++++++++0 | 32
7 | 2 | ++++++++0++++++++00++++++++0++++++++0 | 37
7 | 3 | ++++++++++00++++++++++00++++++++++++0 | 37
8 en 9 | 1 | +++++++++++++++00+++++++++++++++00 | 34
8 en 9 | 2 | ++++++++++0++++++++++++0++++++++++++0 | 37
8 en 9 | 3 | ++++++++++0++++++++++++++++++++0 | 32
10 | 1 | 30 minuten hardlopen met 1 of 2 minuten wandelen naar keuze | 31 of 32
10 | 2 | 32 minuten hardlopen met 1 of 2 minuten wandelen naar keuze | 33 of 34
10 | 3 | 30 minuten hardlopen zonder wandelen | 30
Legenda: + betekent: 1 minuut hardlopen; 0 betekent: 1 minuut wandelen$$, 'inline'),
  ('9a27db58-6c01-4beb-ae8f-fed81fea89e9', '49253b7b-b9a4-4551-adc1-54871cd9312b', $$uitleg schema; na tien weken een halfuur hardlopen; constante snelheid$$,
   $$wiskunde-a-havo-2016-i-start-to-run-context2.png$$,
   $$In het schema kun je aflezen dat je op trainingsdag 1 van week 1 eerst tweemaal om en om één minuut moet hardlopen en één minuut moet wandelen, daarna tweemaal twee minuten moet hardlopen en twee minuten moet wandelen en ten slotte drie minuten moet hardlopen en drie minuten moet wandelen. Daarmee ben je 18 minuten bezig. Het programma is zo opgesteld dat je na tien weken een halfuur zonder onderbreking kunt hardlopen. Het gaat bij Start to Run niet om de snelheid waarmee je hardloopt, dat komt later. Er wordt juist geadviseerd om gedurende deze tien weken de hardloopsnelheid constant te houden.$$, 'inline'),
  ('d83ad4ba-006f-43bd-97ce-991137446b10', '49253b7b-b9a4-4551-adc1-54871cd9312b', $$mevrouw Harmsen in week 9: hardlopen 140 m/min, wandelen 50 m/min$$,
   $$wiskunde-a-havo-2016-i-start-to-run-context3.png$$,
   $$Mevrouw Harmsen traint volgens het programma en is inmiddels in week 9. Haar hardloopsnelheid is steeds 140 meter per minuut en haar wandelsnelheid is steeds 50 meter per minuut.$$, 'inline'),
  ('eb0aaebf-f4e4-415e-b17c-d34339296473', '49253b7b-b9a4-4551-adc1-54871cd9312b', $$meneer Saddal: 9 km/uur, 2,5 keer zijn wandelsnelheid; formule A = 0,15 · H + 0,06 · W$$,
   $$wiskunde-a-havo-2016-i-start-to-run-context4.png$$,
   $$Meneer Saddal volgt het programma van Start to Run ook. Zijn hardloopsnelheid is gedurende het hele programma 9 km per uur. Dit is tweeënhalf keer zo hoog als zijn wandelsnelheid. Je kunt een formule opstellen voor de totale afstand die meneer Saddal per trainingsdag aflegt. Deze formule luidt:
A = 0,15 · H + 0,06 · W
Hierin is A de totale afgelegde afstand in km, H het aantal hardloopminuten en W het aantal wandelminuten.$$, 'inline'),
  ('bb0e7152-b77b-4363-8185-fc0bb17e3dea', '49253b7b-b9a4-4551-adc1-54871cd9312b', $$meneer Saddal: laatste trainingsdag week 10 versus eerste trainingsdag week 1$$,
   $$wiskunde-a-havo-2016-i-start-to-run-context5.png$$,
   $$Meneer Saddal legt op de laatste trainingsdag van week 10, als hij een halfuur lang zonder onderbreking kan hardlopen, een veel grotere afstand af dan op de eerste trainingsdag van week 1.$$, 'inline'),
  ('6f09700d-57f1-4d1a-86a1-619af5430c99', '49253b7b-b9a4-4551-adc1-54871cd9312b', $$training van een uur: W = 60 − H; herleiden tot A = a · H + b$$,
   $$wiskunde-a-havo-2016-i-start-to-run-context6.png$$,
   $$Meneer Saddal krijgt de smaak te pakken en gaat na de periode van
10 weken door met hardlopen. Hij besluit om een uur lang te gaan trainen. Tijdens het hardlopen houdt hij zijn gebruikelijke snelheid aan. Lukt dat niet, dan houdt hij één of meer minuten wandelpauze. Voor een training van een uur geldt dan: W = 60 − H
Hierin is W het aantal wandelminuten en H het aantal hardloopminuten. Als je de formule van W invult in de formule van A, ontstaat een formule van A die alleen nog afhangt van het aantal hardloopminuten H. Deze nieuwe formule van A is te herleiden tot de vorm A = a · H + b , waarbij a en b getallen zijn.$$, 'inline'),
  ('2f594147-9fba-4427-9c8f-29f3e871dde6', '49253b7b-b9a4-4551-adc1-54871cd9312b', $$uitwerkbijlage vraag 11: assenstelsel afgelegde afstand tegen tijd$$,
   $$wiskunde-a-havo-2016-i-start-to-run-context7.png$$,
   $$11
uitwerkbijlage: leeg assenstelsel met afgelegde afstand (meter, 0 t/m 5000) verticaal en tijd (minuten, 0 t/m 34) horizontaal$$, 'uitwerkbijlage'),
  ('32912dd8-1edc-4c23-b233-a5470cdd6cb6', '3ceff3d6-0a84-4ecf-963a-07b844b6b4f0', $$Gammacell met cesium; straling halveert in ongeveer 30 jaar; halveringstijd en vuistregel van tien halveringstijden; foto$$,
   $$wiskunde-a-havo-2016-i-opslag-van-radioactief-afval-context1.png$$,
   $$Een Gammacell is een apparaat dat onder andere gebruikt wordt bij onderzoek naar de bederfelijkheid van voedsel. De Gammacell is een stalen kast waarin zich de radioactieve stof cesium bevindt. Zie de foto.
De hoeveelheid radioactieve straling van cesium neemt jaarlijks met een vast percentage af en is na ongeveer 30 jaar gehalveerd.
De tijd waarin de hoeveelheid straling tot de helft is afgenomen, wordt de halveringstijd genoemd. Soms wordt de volgende vuistregel gebruikt: ''Na tien keer de halveringstijd is het radioactieve materiaal zijn straling kwijt.''
Volgens deze vuistregel zou cesium dus na 300 jaar zijn straling kwijt zijn. Dat is niet helemaal juist. Er is nog een klein beetje van de beginstraling over.$$, 'inline'),
  ('fb8d3b65-a2c2-405b-8ec6-44d2c39cd97e', '3ceff3d6-0a84-4ecf-963a-07b844b6b4f0', $$deel tegengehouden straling door stalen wand: D = 1 − 1/2,058^(0,1d)$$,
   $$wiskunde-a-havo-2016-i-opslag-van-radioactief-afval-context2.png$$,
   $$De stalen wand van de kast, waarin zich de stof cesium bevindt, houdt veel van de radioactieve straling tegen. Het deel van de straling dat tegengehouden wordt door de stalen wand, geven we aan met D. Hiervoor geldt de formule:
D = 1 − 1/2,058^(0,1d)
⚠️ CONTROLEREN: in de bron-PDF ontbreekt de tekst die d en g definieert (de vorm van de formule met g waar vraag 17 naar vraagt).$$, 'inline'),
  ('24c8c8b4-f293-4d9d-bb63-cbcac1f30644', '3ceff3d6-0a84-4ecf-963a-07b844b6b4f0', $$8% doorgelaten door staal; beton laat percentage P = 100/1,021ᵈ door; samen 5%$$,
   $$wiskunde-a-havo-2016-i-opslag-van-radioactief-afval-context3.png$$,
   $$Afgedankte Gammacellen worden verwerkt en opgeslagen door het bedrijf Covra in Borssele. Het bedrijf moet ervoor zorgen dat uit zo''n Gammacell heel weinig straling vrijkomt wanneer deze wordt opgeslagen.
Een Gammacell met een stalen wand van 35 cm dik werkt niet goed meer en wordt afgedankt. Je kunt berekenen dat de stalen wand van deze Gammacell 8% van de straling doorlaat die het cesium heeft op het moment dat het bij Covra binnenkomt. Omdat dat percentage voor opslag te veel is, wordt de hele Gammacell ingepakt in beton. Van de straling die door het staal heen komt, wordt een percentage P door het beton doorgelaten. Dit percentage hangt af van de dikte van het beton. Er geldt de formule:
P = 100/1,021ᵈ
Hierin is d de dikte van het beton in cm.
Het bedrijf moet de dikte van het beton zo kiezen, dat het staal en het beton samen 5% van de straling doorlaten die het cesium op het moment van binnenkomst heeft.$$, 'inline'),
  ('41c6b0e8-7f79-4dc2-83a9-e9b82ec8964a', '23378b2c-a912-4d34-b577-d577ad5be0b6', $$tol per passage voor de Westerscheldetunnel (tarieven 2013)$$,
   $$wiskunde-a-havo-2016-i-door-de-westerscheldetunnel-context1.png$$,
   $$De Westerscheldetunnel verbindt Zeeuws-Vlaanderen met de rest van Nederland. Voor ieder voertuig, waarmee gebruikgemaakt wordt van de tunnel, moet tol betaald worden. In deze opgave gaan we uit van de tarieven die in 2013 golden per passage (enkele reis). Zie figuur 1.$$, 'inline'),
  ('28375af4-1ddb-4c65-a367-a96f4e7df83c', '23378b2c-a912-4d34-b577-d577ad5be0b6', $$figuur 1: tarieven per categorie (standaard, t-tag, veelgebruikerstarief) en uitleg tarieven$$,
   $$wiskunde-a-havo-2016-i-door-de-westerscheldetunnel-context2.png$$,
   $$figuur 1: Tarieven per enkele passage inclusief 21% BTW geldig voor 2013
Categorie | Standaard | t-tag | Veelgebruikerstarief
1 personenauto''s zonder aanhanger | € 5,00 | € 3,80 | € 3,05
2 personenauto''s met aanhanger | € 7,45 | € 5,70 | € 4,55
3 kleine (bestel)bussen, kleine vrachtwagens | € 18,20 | € 13,90 | € 11,15
4 grote vrachtwagens | € 25,00 | € 19,00 | € 15,25
5 motoren | € 2,50 | € 2,50 | € 2,00
Voor elke categorie bestaan er drie verschillende tarieven:
• Wie maar af en toe gebruikmaakt van de tunnel, betaalt het standaardtarief.
• Vaste klanten zijn goedkoper uit: zij bestellen eenmalig gratis de zogenaamde t-tag, een elektronisch apparaat waarmee automatisch wordt betaald. Vervolgens betalen zij bij elke passage het t-tagtarief.
• Daarnaast krijgen vaste klanten met t-tag nog meer korting indien zij vaak gebruik maken van de tunnel: voor elke passage na de 150e passage in een kalenderjaar betalen zij het nog lagere veelgebruikerstarief.$$, 'inline'),
  ('006844d0-009a-4225-bc4b-154657b988c8', '23378b2c-a912-4d34-b577-d577ad5be0b6', $$meneer Dingemanse: 200 werkdagen per jaar heen en terug met personenauto zonder aanhanger$$,
   $$wiskunde-a-havo-2016-i-door-de-westerscheldetunnel-context3.png$$,
   $$Meneer Dingemanse woont in Middelburg en werkt 200 dagen per kalenderjaar in Terneuzen. Op deze dagen maakt hij heen en terug gebruik van de Westerscheldetunnel. Hij rijdt in een personenauto zonder aanhanger. Met de t-tag is hij veel goedkoper uit dan wanneer hij telkens het standaardtarief zou betalen.$$, 'inline'),
  ('e4681792-4395-474b-b571-fce53760be74', '23378b2c-a912-4d34-b577-d577ad5be0b6', $$totale kosten K bij t-tag als functie van het aantal passages p; figuur 2: grafiek in twee gedeelten$$,
   $$wiskunde-a-havo-2016-i-door-de-westerscheldetunnel-context4.png$$,
   $$Voor de bestuurder van een personenauto zonder aanhanger die gebruikmaakt van de t-tag, hangen de totale kosten K in een kalenderjaar af van het aantal passages p in dat jaar. De grafiek van K bestaat uit twee gedeelten, waarbij het tweede gedeelte minder steil loopt. In figuur 2 is een schets gemaakt van deze grafiek.
figuur 2: schets van de grafiek van K (€) tegen p, met een knik bij p = 150$$, 'inline'),
  ('761960ad-feaa-4c86-a061-1905acc034fb', '23378b2c-a912-4d34-b577-d577ad5be0b6', $$K = 11,15 · p + 412,5 inclusief 21% btw; K zonder btw = a · p + b$$,
   $$wiskunde-a-havo-2016-i-door-de-westerscheldetunnel-context5.png$$,
   $$Bij het veelgebruikerstarief voor kleine (bestel)bussen hoort vanaf de 150e passage de formule:
K = 11,15 · p + 412,5
Hierin zijn K de kosten in euro''s en is p het aantal passages in een kalenderjaar.
De formule geeft de kosten K inclusief 21% btw. In sommige situaties werkt men liever met een formule voor de kosten zonder btw. Deze formule kan worden herleid uit de formule van K en heeft de vorm:
K zonder btw = a · p + b
Hierin zijn a en b getallen en is p het aantal passages in een kalenderjaar.$$, 'inline'),
  ('ae5ef4b9-c51a-41f3-9d57-c8e242eb087f', 'd2ff0575-0f86-4e95-a478-4c57f70f4275', $$aantal vrouwelijke leden van voetbalclubs 2002-2014, jeugd en senioren; percentage senioren daalt$$,
   $$wiskunde-a-havo-2016-i-vrouwenvoetbal-context1.png$$,
   $$Vrouwenvoetbal is in. Steeds meer vrouwen en meisjes in Nederland zijn lid van een voetbalclub. In de figuur zie je de ontwikkeling van het aantal vrouwelijke leden van voetbalclubs in de periode 2002 tot en met 2014, telkens gemeten op 1 juli van het betreffende jaar. In de figuur is onder andere te zien dat zowel bij de jeugd als bij de senioren het aantal leden toeneemt. Omdat het aantal leden bij de jeugd sneller groeit dan bij de senioren, wordt het percentage senioren bij de voetbalsters steeds lager. In 2002 was nog iets meer dan 50% van de voetbalsters senior, in 2014 was dat percentage geslonken tot minder dan 40%.$$, 'inline'),
  ('a3cde26c-026c-4c7f-b69a-f8400f2fe928', 'd2ff0575-0f86-4e95-a478-4c57f70f4275', $$figuur: ontwikkeling aantal leden jeugd en senioren met lineaire trendlijnen$$,
   $$wiskunde-a-havo-2016-i-vrouwenvoetbal-context2.png$$,
   $$figuur: aantal vrouwelijke leden (× 1000) van 1 juli 2002 t/m 1 juli 2014 voor jeugd (junioren en pupillen) en senioren, met per groep een rechte lijn die de ontwikkeling benadert$$, 'inline'),
  ('85df4ffc-0853-48c9-a50e-676002c4bcfa', 'd2ff0575-0f86-4e95-a478-4c57f70f4275', $$lineaire verbanden voor jeugd en senioren; percentage senioren voor het eerst lager dan 35%$$,
   $$wiskunde-a-havo-2016-i-vrouwenvoetbal-context3.png$$,
   $$De ontwikkeling van zowel het aantal leden bij de jeugd als bij de senioren is te benaderen door een lineair verband. De bijbehorende lijnen zijn in de figuur weergegeven. We gaan ervan uit dat de aantallen leden van de beide groepen zich volgens de getekende lijnen zullen blijven ontwikkelen. Het percentage senioren zal dan nog verder afnemen.
In een bepaald jaar zal op 1 juli het percentage senioren voor het eerst lager zijn dan 35% van het totaal aantal leden.$$, 'inline');

